class Persona:
    def __init__(self, nombre: str, edad: int):
        self.nombre = nombre
        self.edad = edad

    def saludar(self) -> str:
        return f"Hola, soy {self.nombre} y tengo {self.edad} años"

p = Persona("Ana", 20)
print(p.saludar())

class Contador:
    total = 0  # atributo de clase

    def __init__(self):
        Contador.total += 1

    @classmethod
    def creados(cls) -> int:
        return cls.total

_ = Contador(); _ = Contador(); _ = Contador()
print("Creados:", Contador.creados())

class Producto:
    def __init__(self, nombre: str, precio: float):
        self.nombre = nombre
        self.precio = precio

    @property
    def precio(self) -> float:
        return self._precio

    @precio.setter
    def precio(self, value: float) -> None:
        if value < 0:
            raise ValueError("El precio no puede ser negativo")
        self._precio = float(value)

p = Producto("Mouse", 10)
print(p.precio)

class Animal:
    def __init__(self, nombre: str):
        self.nombre = nombre

    def hablar(self) -> str:
        return "..."

class Perro(Animal):
    def __init__(self, nombre: str, raza: str):
        super().__init__(nombre)
        self.raza = raza

    def hablar(self) -> str:
        return "guau"

print(Perro("Bobby", "Labrador").hablar())

class Item:
    def __init__(self, nombre: str, precio: float):
        self.nombre = nombre
        self.precio = precio

class Carrito:
    def __init__(self):
        self.items: list[Item] = []

    def agregar(self, item: Item) -> None:
        self.items.append(item)

    def total(self) -> float:
        return sum(i.precio for i in self.items)

c = Carrito()
c.agregar(Item("Pan", 1.5))
c.agregar(Item("Leche", 0.9))
print("Total:", c.total())

def leer_entero(texto: str) -> int:
    try:
        return int(texto)
    except ValueError:
        return 0

print(leer_entero("123"))
print(leer_entero("hola"))

from dataclasses import dataclass

@dataclass
class Alumno:
    cuenta: str
    nombre: str

class Repositorio:
    def __init__(self):
        self.items: list[Alumno] = []

    def agregar(self, a: Alumno):
        if any(x.cuenta == a.cuenta for x in self.items):
            raise ValueError("Cuenta duplicada")
        self.items.append(a)

    def buscar(self, cuenta: str) -> Alumno | None:
        return next((x for x in self.items if x.cuenta == cuenta), None)
